import{_ as a,o as n,c as t,a3 as e}from"./chunks/framework.Dz5Q8p4s.js";const h=JSON.parse('{"title":"RoboSynChallenge: Mastering Real-World Dexterity via Generalizing Synthesized Manipulation Skills","description":"","frontmatter":{"title":"RoboSynChallenge: Mastering Real-World Dexterity via Generalizing Synthesized Manipulation Skills","arxiv":"2608.12416","date":"2026-08-12","authors":"Runyi Zhao, Ruixin Wu, Chengkun Li, Hongrui Zhang, Ang Li, Ruixing Jin, Yueci Deng, Yingying Guo, Lihe Ding, Shaocong Dong, Tianfan Xue, Yanjun Gao, Yudong Luo, Pascal Poupart, Simo Wu, Kui Jia, Wei-shi Zheng, Guiliang Liu","categories":"cs.RO","topics":"Sim2Real 基准, 合成数据, 双臂灵巧操作","outline":[2,2]},"headers":[],"relativePath":"papers/2608.12416.md","filePath":"papers/2608.12416.md","lastUpdated":null}'),p={name:"papers/2608.12416.md"};function l(i,s,r,o,m,g){return n(),t("div",null,[...s[0]||(s[0]=[e('<h1 id="robosynchallenge-mastering-real-world-dexterity-via-generalizing-synthesized-manipulation-skills" tabindex="-1">RoboSynChallenge: Mastering Real-World Dexterity via Generalizing Synthesized Manipulation Skills <a class="header-anchor" href="#robosynchallenge-mastering-real-world-dexterity-via-generalizing-synthesized-manipulation-skills" aria-label="Permalink to &quot;RoboSynChallenge: Mastering Real-World Dexterity via Generalizing Synthesized Manipulation Skills&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2608.12416" target="_blank" rel="noreferrer">2608.12416</a></td></tr><tr><td><strong>提交日期</strong></td><td>2026-08-12（v1，唯一版本）</td></tr><tr><td><strong>会议</strong></td><td>NeurIPS 2026 Competition Track</td></tr><tr><td><strong>作者</strong></td><td>Runyi Zhao, Ruixin Wu, Chengkun Li, Hongrui Zhang, Ang Li, Ruixing Jin, Yueci Deng, Yingying Guo, Lihe Ding, Shaocong Dong, Tianfan Xue, Yanjun Gao, Yudong Luo, Pascal Poupart, Simo Wu, Kui Jia, Wei-shi Zheng, Guiliang Liu（深圳河套研究院 SLAI、港中深、港中文、港科大、DexForce 等）</td></tr><tr><td><strong>分类</strong></td><td>cs.RO</td></tr><tr><td><strong>一句话</strong></td><td>一份 NeurIPS 2026 竞赛提案：用 EmbodiChain 每个任务生成 1000 条仿真轨迹配 60 条真机遥操作数据，鼓励参赛者用合成数据训练，但排行榜只在未见的真实双臂环境上评测，官方基线覆盖 Transformer / Diffusion / VLA / World-Action-Model 四类。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/video-to-wam">从视频生成到世界动作模型</a></p></blockquote><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>通用机器人操作的进展受限于真实数据的稀缺与多样性不足。视觉与语言模型可以吃互联网规模的语料，机器人不行——操作数据必须通过物理交互获得，采集慢、贵、且绑死在特定硬件上。</p><p>仿真是显而易见的出路，但动力学、运动学与传感的失配带来 Sim2Real gap。于是问题变成一个<strong>评测问题</strong>：怎样公平地量化&quot;合成数据在真实数据稀缺时到底能把策略的泛化能力提升多少&quot;。</p><p>作者指出现有 benchmark 的两个结构性缺陷。其一，它们要么纯仿真（RLBench、CALVIN、LIBERO、RoboTwin），要么纯真实（RoboChallenge、RobotArena、RoboArena、ManipulationNet、ManipArena），<strong>没有一个把&quot;用仿真数据训练&quot;与&quot;在真实环境评测&quot;接起来</strong>。其二，绝大多数依赖固定数据集，隐含&quot;环境静态可控&quot;的假设，这与&quot;策略必须泛化到未见物体与多样环境&quot;的目标直接冲突。</p><p>RoboSynChallenge 的设计因此有一条很硬的规则：<strong>参赛者被鼓励用合成的 state-action trial 训练，但最终评估只在未见的真实操作环境上做</strong>。这条规则让整个竞赛变成一次对 Sim2Real 可迁移性的大规模受控测量，而不是又一次刷榜。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>论文的表 1 沿八个维度对比既有竞赛与 benchmark：刚体、铰接体、装配、工具使用、操作设置（单臂/双臂）、数据集类型、训练环境、评测环境。</p><p><strong>纯仿真一支</strong>：RLBench、CALVIN、LIBERO 都是单臂、离线数据集、仿真训练+仿真评测，且不覆盖装配与工具使用；RoboTwin 覆盖到工具使用与双臂，但训练与评测仍全在仿真里。</p><p><strong>纯真实一支</strong>：WBCD 是双臂、真实训练+真实评测但<strong>不提供数据集</strong>；RoboChallenge 覆盖四类物体与单双臂；RobotArena$\\infty$ 单臂、无数据集；RoboArena 反过来——真实训练、<strong>仿真评测</strong>；ManipulationNet 与 ManipArena 都是单臂或无铰接/装配覆盖。</p><p>RoboSynChallenge 在表 1 里是唯一一行在四类物体全打勾、双臂、<strong>数据集类型为 &quot;Generative&quot;</strong>、训练环境 &quot;Sim. &amp; Real.&quot;、评测环境 &quot;Realistic&quot; 的条目。作者据此声称三点差异：(1) 首个标准化的 Sim2Real 可迁移性 benchmark，评的不只是原始性能还有真实噪声与域偏移下的稳健性；(2) <strong>生成式数据流</strong>——不是固定的人工数据集，而是一条闭环的自动数据生成流水线，且参赛者可以拿提供的真实数据去喂风格迁移模型、视频生成模型（Wan）或场景增广技术来合成更多高保真轨迹；(3) 真实机器人评测直接构成官方排行榜的一部分，用与仿真相同的任务定义与指标。</p><p>需要注意的是，这是一份<strong>竞赛提案</strong>（proposal），表 1 的对比是设计层面的定位，不是实验结论。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>第一步是承认一个已被反复验证的事实：机器人策略的泛化瓶颈在数据，而真实数据的成本结构短期内不会改变。第二步是问“仿真数据到底值多少”。这个问题在文献里有大量各说各话的答案，根本原因是<strong>没有共同的度量尺</strong>：每篇论文用自己的仿真器、自己的真机、自己的任务。于是要造尺子，而不是造方法。</p><p>第三步是设计尺子的关键约束。训练与评测都在仿真里测的是 Sim2Sim，都在真实里测的是 Real2Real；只有<strong>训练可以用仿真、评测强制在真实且未见的环境</strong>，测出来的才是 Sim2Real 可迁移性。这一条决定了整个竞赛的形态。</p><p>第四步是让“仿真数据”本身可扩展。固定数据集会立刻被过拟合，所以接入 EmbodiChain 这类可程序化生成环境、闭环产出运动轨迹的框架，让数据成为一个<strong>流</strong>而非一个<strong>集合</strong>；同时提供少量真机数据作为 Sim2Real 的锚点。第五步是把“泛化”拆成可以逐因子测量的轴，于是有了 one-factor-at-a-time 协议：背景、光照、物体、干扰物、空间位置各自单独变化，其余固定。</p><p>第六步是给基线。为了让比较有意义，需要覆盖当前主流的四类策略族——序列建模（ACT）、生成式动作预测（Diffusion Policy）、VLA（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">0.5</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>）、世界动作模型（Motus）。<strong>WAM 进入官方基线</strong>本身就是一个信号：到 2026 年中，WAM 已被竞赛组织者当作与 VLA 并列的主流策略族。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>&quot;合成数据有多大用&quot;之所以吵不出结论，是因为每个人都在自己的尺子上量。把尺子统一成一条硬规则——训练随你用什么数据，评测一律在你没见过的真实双臂工位上做——这个问题就变成可测量的。再把数据从固定集合换成可程序化生成的流，参赛者优化的就不再是&quot;怎么在这份数据上过拟合&quot;，而是&quot;怎么生成对真实世界有用的数据&quot;。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p><strong>硬件与工位。</strong> 双臂平台由两台 AgileX Piper 6-DoF 机械臂组成。工作台高度可调、桌布纹理可换、照明可配置。为了支撑多轮真实测试，组织方准备了<strong>三套与主工位配置相同的备用工位</strong>。所有任务只依赖视觉观测与本体感觉反馈。</p><p><strong>真机数据采集协议。</strong> 每个操作任务在<strong>五种不同实验条件</strong>下采集，每种条件再跨<strong>四个位置变体</strong>与<strong>三个朝向设定</strong>，即每任务 60 个样本。五种条件在背景纹理、照明与场景复杂度上引入变化。</p><p><strong>合成数据生成协议。</strong> 用 EmbodiChain 扩展仿真 state-action trail。每个仿真实例对照明、物体属性、桌面属性、背景颜色、机器人配置做系统性扰动；相机内参与外参也被随机化以模拟不同视角与成像条件。**每个任务随机采样变体生成 1000 条操作 trial。**完整数据采集流水线开源。此外，因为提供了真实数据，参赛者可以用它通过 in-context learning 或 fine-tuning 去引导视频生成模型（Wan），生成的数据还能进一步用场景增广技术精炼。</p><p><strong>任务谱系（共 10 个）。</strong></p><ul><li><em>入门级</em>（4 个）：table rearrangement、click-bell、water pouring、handle basket。短时程、低接触复杂度、affordance 清晰，考察稳定感知、可靠抓取与一致运动轨迹。</li><li><em>中级</em>（3 个）：items hand-over、drawer open-and-place、mixer operating。复合的序贯交互，引入可变接触条件、多物体依赖与部分规划时程，考察阶段间平滑过渡与力调节一致性。</li><li><em>高级</em>（3 个）：item assembly、pipette manipulation、sample loading。细粒度与领域特定操作，要求高精度、多阶段排序与动态适应，考察对齐精度、流程一致性与偏差下的恢复能力。</li></ul><p><strong>评测协议。</strong> 五类真实变化：背景（木纹、蓝布、黄格三种桌面纹理）、光照（三个光源位置与不同色温）、物体（同类别的已见与未见实例）、干扰物（2 / 4 / 8 三个难度档，取自与任务物体分离的物体集）、空间泛化（预定义 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">3</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">3</span></span></span></span> 网格上的未见位置）。先在 canonical base 配置下评测，然后<strong>一次只变一个因子</strong>、其余固定；每个配置下再对物体位置施加小的随机平移多次评测。</p><p><strong>指标（三个）。</strong> Success Rate（按 Table 5 的预定义成功判据）；Inference Time（产出可执行指令的速度，<strong>所有模型部署在同一台 NVIDIA A800 机器上</strong>以保证公平）；Action Steps（完成任务所用的控制步数，上限 1000）。</p><p><strong>防泄漏设计。</strong> 评测不需要访问测试数据或任何 ground-truth 标签，直接在真实世界里判定结果；训练数据只包含<strong>成功轨迹</strong>；测试环境相对训练观测是分布外的 held-out 环境。数据集以 CC BY-NC-SA 4.0 发布给注册参赛者。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>本文无形式化数学推导，跳过。</p><p>（这是一份竞赛提案，贡献是数据生成与评测协议的工程设计，指标为成功率、推理时间与控制步数的直接计数，全文不含形式化定义或定理。）</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p>论文报告了一组初始基线实验（表 2），口径是<strong>每任务 20 次真机 trial</strong>，报 SR（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">x</span><span class="mord">/20</span></span></span></span>）、Action Steps（上限 1000）与 Real Time（秒）。参与评测的是 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">0.5</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>、Motus 三个模型，每个各有 <strong>sim（仅用仿真数据训）</strong> 与 <strong>real（仅用真机数据训）</strong> 两个版本。</p><p><strong>十任务平均（SR / Steps / Time）</strong>：<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> (sim) 22.00% / 898.12 / 90.56；<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> (real) 22.50% / 881.15 / 90.20；<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">0.5</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> (sim) <strong>38.50%</strong> / 797.55 / 80.55；<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">0.5</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> (real) 33.00% / 821.65 / 82.35；Motus (sim) 31.50% / 778.80 / 133.76；Motus (real) 27.50% / <strong>721.35</strong> / 129.43。</p><p><strong>问题一：仿真数据训练能不能打过真机数据训练？</strong> 对 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">0.5</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>（38.50 vs 33.00）与 Motus（31.50 vs 27.50），<strong>只用仿真数据训出来的策略在真机上反而更好</strong>；<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 两者基本持平（22.00 vs 22.50）。这是一个正面结果，但必须立刻加上一句：<strong>每任务的仿真数据是 1000 条，真机数据是 60 条</strong>，两者相差约 17 倍。所以这个对比同时改变了&quot;数据来源&quot;与&quot;数据体量&quot;两个因子，不能读成&quot;仿真数据质量更高&quot;。论文没有做等量对照。</p><p><strong>问题二：任务难度谱设计得合理吗？</strong> 从表 2 看是合理的，而且有一个非常干净的地板证据：<strong>item assembly 上六个配置全部 0/20</strong>，Action Steps 全部 1000.00（即耗尽预算）。这说明高级任务确实超出当前策略能力，竞赛有充分的头部空间。相应地，入门级任务的分数分布很宽——table rearrangement 上 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">0.5</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 拿 12/20 而 Motus 只有 3–4/20；click bell 上 Motus 拿 13–14/20 而 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 只有 5–8/20。<strong>不同策略族的强弱任务完全不同</strong>，没有一个模型横扫，这对一个竞赛 benchmark 是好性质。</p><p><strong>问题三：Action Steps 是一个好的效率指标吗？</strong> 这里论文自己埋了一个诚实的注解：&quot;更高的计数可能表明因错误检测、反馈与解决而增加的延迟，<strong>也可能反映任务未完成、动作预算被耗尽的未解决失败</strong>&quot;。后半句意味着 Steps 与 SR 在机制上高度耦合——失败必然刷满 1000 步。但数据显示两者并非简单单调：Motus (real) 平均 721.35 步却只有 27.5% 成功率，而 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">0.5</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> (sim) 平均 797.55 步却有 38.5%。也就是说 <strong>Motus 用更少的控制步拿到更低的成功率</strong>。与此同时 Motus 的 Real Time 是 129–134 秒，远高于两个 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">π</span></span></span></span> 模型的 80–91 秒——因为它每步推理更慢。<strong>Steps 与 Time 给出相反的排序</strong>，说明单看任一个都会误导，必须一起看。这是这份基线表里最值得记的一条方法论观察。</p><p><strong>必须写下的证据缺口。</strong></p><p>其一，<strong>摘要与 §1.5 承诺的五类基线，表 2 只报了三个</strong>。ACT 与 Diffusion Policy 被列入基线族并给出了详细描述，但没有任何数字。论文的措辞是&quot;当前已评测的 VLA 与 WAM 基线的初始实验结果&quot;，属于诚实的限定，但摘要里&quot;Baseline implementations, including Transformer-, Diffusion-, Vision-Language-Action, and World-Action-Model-based policies, are provided&quot;读起来像是四类都已就绪。</p><p>其二，<strong>竞赛的核心假设——sim + real 协同训练——在表 2 里完全没有被测试</strong>。图 1 的流水线图明确画的是&quot;合成数据 + 少量真机数据 → Sim2Real co-training&quot;，正文也写&quot;这些合成数据连同少量静态真机数据可用于 sim-to-real 协同训练&quot;。但表 2 只有 sim-only 与 real-only 两档，<strong>没有 co-training 行</strong>。整份提案要量化的那个量，基线里没有量。</p><p>其三，<strong>没有平凡基线</strong>。表 2 里没有&quot;不动&quot;、&quot;随机动作&quot;或&quot;回放一条固定演示&quot;的对照行。这对本竞赛尤其重要：入门级任务如 click-bell（按响铃铛）与 table rearrangement，其成功判据是否可能被大范围随机扫动偶然满足，从这份提案无法判断。item assembly 全 0 提供的是最难任务的地板，不是简单任务的地板。而排行榜将以 SR 排名，若简单任务上存在可被平凡策略刷到的分数，排名会被污染。</p><p>其四，<strong>每任务 20 次 trial 的统计力很弱</strong>：<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">0.5</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> (sim) 38.50% 与 (real) 33.00% 的差值来自 200 次 trial，二项标准误约 3.4 个百分点，5.5 点大约只是 1.6 个标准误。</p><p>其五，<strong>训练数据只含成功轨迹</strong>，这是防泄漏设计的一部分，但它同时排除了从失败中学习的路线，实际上对方法空间做了限制。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>五句话版。</strong> 合成数据有多大用之所以吵不出结论，是因为每个人都在自己的尺子上量。RoboSynChallenge 造这把尺子：训练可以随便用什么数据，评测一律在未见的真实双臂 AgileX Piper 工位上做，任务分入门/中级/高级三档共 10 个。数据侧每任务提供 1000 条 EmbodiChain 生成的仿真 trial 与 60 条真机遥操样本，评测侧沿背景、光照、物体、干扰物、空间位置五个轴 one-factor-at-a-time 变化，指标是成功率、推理时间与控制步数。官方基线覆盖 ACT / Diffusion Policy / <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> / <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">0.5</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> / Motus 五族，其中 Motus 代表世界动作模型；初始结果里 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">0.5</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 与 Motus 的仿真训练版在真机上反而优于真机训练版（38.5 vs 33.0、31.5 vs 27.5），但仿真数据比真机数据多约 17 倍，item assembly 全部 0/20。</p><p><strong>三句话版。</strong> 一份 NeurIPS 2026 竞赛提案，用&quot;合成数据训练、未见真实环境评测&quot;这条硬规则把 Sim2Real 可迁移性变成可测量的量。10 个双臂任务、三档难度、五轴逐因子扰动协议、四类策略族基线，WAM（Motus）首次进入这类竞赛的官方基线。初始基线显示仿真训练版可以打平甚至超过真机训练版，但数据量未对齐，且提案想量化的 sim+real co-training 本身在基线里缺席。</p><p><strong>一句话版。</strong> 把&quot;仿真数据值多少&quot;从一个各说各话的问题变成一个有统一尺子的竞赛：训练随意，评测只认没见过的真机。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最脆弱的一条是：**真实评测环境相对训练观测确实是分布外的，因此排行榜排名度量的是泛化而非记忆。**这条假设承载了整个竞赛的效度——如果它不成立，排行榜就退化成又一个可以被过拟合的固定 benchmark。</p><p>它在实践中很可能被侵蚀，原因是评测协议本身把变化空间<strong>枚举得太具体</strong>了：三种桌布纹理、三个光源位置、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">3</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">3</span></span></span></span> 网格上的位置、2/4/8 三档干扰物数量。这些取值集合是公开、有限、离散、可枚举的，参赛者完全可以在自己的仿真里<strong>逐一复现</strong>，从而把“未见环境”变成“已见环境的一个已知子集”。真正未见的只剩“未见物体实例”这一轴，而它同样被限定在“同一任务类别内”。</p><p>更细一层的风险是<strong>备用工位</strong>。为了支撑多轮测试准备了三套配置相同的工位——&quot;配置相同&quot;意味着评测环境的多样性在硬件层面被刻意压低了，这与&quot;评测环境应当是 held-out&quot;的目标方向相反（虽然它对可复现性有利）。这里存在一个提案没有讨论的张力。</p><p>论文提供了什么证据？只有设计层面的声明：&quot;评估采用 held-out 测试协议，测试环境相对训练观测是分布外的，确保最小重叠并降低数据泄漏风险。&quot;<strong>没有任何量化的分布距离度量，也没有任何实证检验</strong>（例如：在 held-out 环境上训练一个域分类器，看它能否把评测观测与训练观测区分开；或报告评测场景与训练场景在某个视觉特征空间里的距离分布）。缺的正是这个——一个 benchmark 声称自己的测试集是 OOD 时，应当像报告 baseline 一样报告这个 OOD 程度。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周内可做，不需要真机，也不需要训练任何大模型：<strong>用公开的合成数据管线检验&quot;评测协议的因子空间是否可被枚举复现&quot;</strong>。</p><ul><li>数据：从 RoboSynChallenge 的开源数据生成流水线（EmbodiChain）取任意两个入门级任务（如 click-bell 与 table rearrangement）。</li><li>构造两个训练集，<strong>轨迹条数完全相同</strong>： <ul><li><strong>集合 A（盲配置）</strong>：按论文描述的方式随机化照明、物体属性、桌面属性、背景颜色、相机内外参。</li><li><strong>集合 B（靶向配置）</strong>：把随机化的取值<strong>限制在评测协议公开枚举的那些值上</strong>——三种桌面纹理、三个光源位置、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">3</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">3</span></span></span></span> 网格位置、2/4/8 干扰物档位。</li></ul></li><li>模型：训一个小的 Diffusion Policy 或 ACT（不需要 VLA/WAM 规模），两个集合各训一个，超参完全相同。</li><li>评测：在仿真里搭一个&quot;仿评测环境&quot;，严格按协议的 canonical base + one-factor-at-a-time 生成测试场景，报两个模型的成功率。</li><li>判据：如果集合 B 的模型显著优于集合 A，<strong>说明评测协议的离散因子空间可以被靶向刷分</strong>，&quot;held-out OOD&quot;的效度打折，竞赛需要引入未公开的扰动轴或随机化取值（例如在连续区间上采样纹理与光照而非公布三个具体值）。如果两者相当，说明协议的泛化压力主要来自 Sim2Real 的视觉/动力学 gap 而非因子枚举，效度较好。</li></ul><p>这个实验完全在仿真里做，成本极低，却直接检验了竞赛设计里最关键也最未被验证的那条假设。</p><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>最强的攻击是<strong>在入门级任务上跑平凡基线</strong>，因为这是排行榜最可能被污染的地方，而提案没有提供地板。</p><p>反例实验：在同一套真机工位与同一份成功判据下，为每个任务运行三条不需要学习的策略，每条同样 20 次 trial。</p><ul><li><strong>臂 A（不动）</strong>：机器人保持初始位姿到预算耗尽。这给出每个任务的绝对地板。</li><li><strong>臂 B（回放固定演示）</strong>：从训练集里取一条成功轨迹，在评测的每个配置下原样开环回放，不看观测。这检验成功判据对初始位姿变化的敏感度——如果 table rearrangement 或 click-bell 在部分配置下能被固定回放通过，那么该任务的 SR 里有一部分与&quot;感知与泛化&quot;无关。</li><li><strong>臂 C（约束随机扫动）</strong>：在工作空间内做随机但受限的末端运动（例如在桌面上方做随机往复，夹爪周期开合），持续到预算耗尽。这检验成功判据能否被大范围无目的运动偶然满足——click-bell（按响一个铃铛）与 basket pick-and-place 这类任务对此尤其敏感。</li></ul><p>预测与判据：若臂 C 在任一入门级任务上拿到 3/20 以上，那么该任务在排行榜上的贡献就需要打折——注意 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> (real) 在 click bell 上是 5/20、Motus (real) 在 table rearrangement 上是 3/20，<strong>这两个数字本身就已经落在&quot;可能被平凡策略触及&quot;的量级里</strong>。若臂 B 在多个配置下通过，说明评测的位置/朝向变化幅度不足以强制闭环感知。任一情形成立，都意味着最终排行榜应当报告&quot;相对平凡基线的提升&quot;而非绝对 SR。</p><p>第二类攻击针对 sim-vs-real 的数据量混淆：把仿真训练集从 1000 条<strong>降采样到 60 条</strong>（与真机数据等量），重跑 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">0.5</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 与 Motus 的 sim 版。若等量后仿真版明显低于真机版，那么表 2 里&quot;仿真训练更好&quot;就完全由数据体量解释，而不是数据质量——这会改变整个竞赛叙事的重心（从&quot;仿真数据更有用&quot;变成&quot;仿真数据更便宜所以可以更多&quot;，后者其实是更准确也更有说服力的表述）。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>(a) 驱动它的局限。</strong> 这份提案把参赛者的优化对象定义为&quot;策略&quot;，把数据生成器当作组织方提供的固定基础设施。但它自己的设计逻辑其实指向另一个方向：既然数据是<strong>流</strong>而不是<strong>集合</strong>，且参赛者被允许用真实数据去引导视频生成模型与场景增广，那么真正的决策变量就不只是&quot;用什么模型学&quot;，还有&quot;<strong>生成什么数据</strong>&quot;。当前的评测无法把这两者分开——一个队伍赢了，你不知道是因为它的策略更好还是它的数据配方更好。</p><p><strong>(b) 可借鉴的相邻工具。</strong> 这正是 <strong>dataset distillation / active learning / experimental design</strong> 的设定：在固定的生成预算下选择最有信息量的场景配置。更贴切的是 <strong>domain randomization 的自动化</strong>一支（把随机化分布本身当作可优化对象），以及 <strong>Sim2Real gap 的可辨识性分析</strong>——用少量真机 rollout 去估计&quot;哪些随机化维度真的影响真机表现&quot;。</p><p><strong>(c) 第一个实验长什么样。</strong> 把竞赛拆成两条正交赛道：<strong>固定策略、比数据</strong>，与<strong>固定数据、比策略</strong>。第一个实验只做前者的可行性验证：冻结一个官方基线（例如 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">0.5</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>）的架构、超参与训练预算，让不同的数据生成策略在<strong>同一个仿真 trial 预算</strong>（比如每任务 1000 条）下竞争——一条臂用论文当前的均匀随机化，一条臂用基于少量真机 rollout 反馈的自适应随机化（先跑 20 次真机、按失败模式加权重采样随机化维度，再生成剩余数据）。</p><p>判据很明确：在完全相同的策略与训练预算下，自适应数据配方能否在真机 SR 上超过均匀随机化，超多少。如果这个差值与“换一个更好的策略架构”带来的差值可比（表 2 里 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 到 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">0.5</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 是 22.0 → 38.5，即 16.5 点），那么“数据配方”就应当被承认为一个与“模型架构”同等量级的研究对象，竞赛也应当为它单独设赛道并单独排名。</p>',69)])])}const u=a(p,[["render",l]]);export{h as __pageData,u as default};
